caller:
Create Variable PrivateValue PrivateCost PrivateCalls SharedValue SharedCost SharedCalls ObservedLimit Keep;
Keep = 41;
Create FminconOptimizer SharedOptimizer;
SharedOptimizer.MaximumIterations = 61;
SharedOptimizer.MaxFunEvals = '500';
SharedOptimizer.TolX = '1e-9';
SharedOptimizer.TolFun = '1e-10';
SharedOptimizer.TolCon = '1e-10';
SharedOptimizer.ShowProgress = false;
Global SharedOptimizer;
Create GmatFunction PrivateSolve SharedSolve;
PrivateSolve.FunctionPath = '@FILES@/PrivateSolve.gmf';
SharedSolve.FunctionPath = '@FILES@/SharedSolve.gmf';
BeginMissionSequence;
[PrivateValue, PrivateCost, PrivateCalls] = PrivateSolve();
[SharedValue, SharedCost, SharedCalls, ObservedLimit] = SharedSolve();
Keep = Keep + 1;

functions.PrivateSolve.gmf:
function [Out, Cost, Calls] = PrivateSolve()
Create Variable Out Cost Calls Alpha;
Create FminconOptimizer LocalOptimizer;
LocalOptimizer.MaximumIterations = 60;
LocalOptimizer.MaxFunEvals = '500';
LocalOptimizer.TolX = '1e-9';
LocalOptimizer.TolFun = '1e-10';
LocalOptimizer.TolCon = '1e-10';
LocalOptimizer.ShowProgress = false;
BeginMissionSequence;
Calls = 0;
Optimize LocalOptimizer {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary LocalOptimizer(Alpha = 0, {Lower = -5, Upper = 3, AdditiveScaleFactor = 0, MultiplicativeScaleFactor = 1});
Cost = (Alpha - 4)^2;
Calls = Calls + 1;
Minimize LocalOptimizer(Cost);
EndOptimize;
Out = Alpha;

functions.SharedSolve.gmf:
function [Out, Cost, Calls, Limit] = SharedSolve()
Create Variable Out Cost Calls Alpha Limit;
Global SharedOptimizer;
BeginMissionSequence;
Calls = 0;
Optimize SharedOptimizer {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary SharedOptimizer(Alpha = 0, {Lower = -5, Upper = 4, AdditiveScaleFactor = 0, MultiplicativeScaleFactor = 1});
Cost = (Alpha - 5)^2;
Calls = Calls + 1;
Minimize SharedOptimizer(Cost);
EndOptimize;
Out = Alpha;
Limit = SharedOptimizer.MaximumIterations;
